export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "手紙が届いたのは、火曜日の朝だった。", ruby: [{"start":0,"end":2,"reading":"てがみ"},{"start":3,"end":4,"reading":"とど"},{"start":9,"end":12,"reading":"かようび"},{"start":13,"end":14,"reading":"あさ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王城に郵便配達は来ない。三百年のあいだ、この城に届けられたものは三種類しかなかった。果たし状と、呪いと、勇者本人だ。だから秘書が淡いクリーム色の封筒を玉座の肘掛けに置いたとき、魔王はずいぶん長いことそれを見つめていた。", ruby: [{"start":0,"end":3,"reading":"まおうじょう"},{"start":4,"end":8,"reading":"ゆうびんはいたつ"},{"start":9,"end":10,"reading":"こ"},{"start":13,"end":16,"reading":"さんびゃくねん"},{"start":23,"end":24,"reading":"しろ"},{"start":25,"end":26,"reading":"とど"},{"start":33,"end":36,"reading":"さんしゅるい"},{"start":43,"end":44,"reading":"は"},{"start":46,"end":47,"reading":"じょう"},{"start":49,"end":50,"reading":"のろ"},{"start":53,"end":57,"reading":"ゆうしゃほんにん"},{"start":62,"end":64,"reading":"ひしょ"},{"start":65,"end":66,"reading":"あわ"},{"start":71,"end":72,"reading":"いろ"},{"start":73,"end":75,"reading":"ふうとう"},{"start":76,"end":78,"reading":"ぎょくざ"},{"start":79,"end":81,"reading":"ひじか"},{"start":83,"end":84,"reading":"お"},{"start":89,"end":91,"reading":"まおう"},{"start":96,"end":97,"reading":"なが"},{"start":103,"end":104,"reading":"み"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "封筒の宛名は、とても几帳面な字で書かれていた。封をしていたのは血ではなく、ご飯粒だった。", ruby: [{"start":0,"end":2,"reading":"ふうとう"},{"start":3,"end":5,"reading":"あてな"},{"start":10,"end":13,"reading":"きちょうめん"},{"start":14,"end":15,"reading":"じ"},{"start":16,"end":17,"reading":"か"},{"start":23,"end":24,"reading":"ふう"},{"start":31,"end":32,"reading":"ち"},{"start":38,"end":40,"reading":"はんつぶ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）嫌な予感がする。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":6,"reading":"いや"},{"start":7,"end":9,"reading":"よかん"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "勇者からです。読み上げましょうか。", ruby: [{"start":0,"end":2,"reading":"ゆうしゃ"},{"start":7,"end":8,"reading":"よ"},{"start":9,"end":10,"reading":"あ"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "読め。", ruby: [{"start":0,"end":1,"reading":"よ"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「拝啓　魔王陛下。このたび一身上の都合により、本月末日をもちまして勇者の職を辞することといたしました。」", ruby: [{"start":1,"end":3,"reading":"はいけい"},{"start":4,"end":6,"reading":"まおう"},{"start":6,"end":8,"reading":"へいか"},{"start":13,"end":16,"reading":"いっしんじょう"},{"start":17,"end":19,"reading":"つごう"},{"start":23,"end":27,"reading":"ほんげつまつじつ"},{"start":33,"end":35,"reading":"ゆうしゃ"},{"start":36,"end":37,"reading":"しょく"},{"start":38,"end":39,"reading":"じ"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「十二年間、大変お世話になりました。攻め込むたびに、貴城の細やかなお心配りを感じておりました。罠の手入れは常に行き届き、口上も一度として同じものはございませんでした。」", ruby: [{"start":1,"end":5,"reading":"じゅうにねんかん"},{"start":6,"end":8,"reading":"たいへん"},{"start":9,"end":11,"reading":"せわ"},{"start":18,"end":19,"reading":"せ"},{"start":20,"end":21,"reading":"こ"},{"start":26,"end":28,"reading":"きじょう"},{"start":29,"end":30,"reading":"こま"},{"start":34,"end":36,"reading":"こころくば"},{"start":38,"end":39,"reading":"かん"},{"start":47,"end":48,"reading":"わな"},{"start":49,"end":51,"reading":"てい"},{"start":53,"end":54,"reading":"つね"},{"start":55,"end":56,"reading":"い"},{"start":57,"end":58,"reading":"とど"},{"start":60,"end":62,"reading":"こうじょう"},{"start":63,"end":65,"reading":"いちど"},{"start":68,"end":69,"reading":"おな"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）口上は毎年、書き直しているからな。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"こうじょう"},{"start":8,"end":10,"reading":"まいとし"},{"start":11,"end":12,"reading":"か"},{"start":13,"end":14,"reading":"なお"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「ですが私も今年で三十四になり、膝の具合が思わしくありません。前回、第七層の回転刃の罠を転がり抜けた折には、ひと月寝込みました。人生には、ほかにもやれることがあるのではないかと思うようになりました。」", ruby: [{"start":4,"end":5,"reading":"わたし"},{"start":6,"end":8,"reading":"ことし"},{"start":9,"end":12,"reading":"さんじゅうよん"},{"start":16,"end":17,"reading":"ひざ"},{"start":18,"end":20,"reading":"ぐあい"},{"start":21,"end":22,"reading":"おも"},{"start":31,"end":33,"reading":"ぜんかい"},{"start":34,"end":37,"reading":"だいななそう"},{"start":38,"end":41,"reading":"かいてんば"},{"start":42,"end":43,"reading":"わな"},{"start":44,"end":45,"reading":"ころ"},{"start":47,"end":48,"reading":"ぬ"},{"start":50,"end":51,"reading":"おり"},{"start":56,"end":57,"reading":"つき"},{"start":57,"end":59,"reading":"ねこ"},{"start":64,"end":66,"reading":"じんせい"},{"start":88,"end":89,"reading":"おも"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「東の山のふもとに土地を買い、かぶを育てるつもりです。土はよく、ご近所の方々も親切です。末筆ながら、貴城の魔業のますますのご発展をお祈り申し上げます。敬具　勇者」", ruby: [{"start":1,"end":2,"reading":"ひがし"},{"start":3,"end":4,"reading":"やま"},{"start":9,"end":11,"reading":"とち"},{"start":12,"end":13,"reading":"か"},{"start":18,"end":19,"reading":"そだ"},{"start":27,"end":28,"reading":"つち"},{"start":33,"end":35,"reading":"きんじょ"},{"start":36,"end":38,"reading":"かたがた"},{"start":39,"end":41,"reading":"しんせつ"},{"start":44,"end":46,"reading":"まっぴつ"},{"start":50,"end":52,"reading":"きじょう"},{"start":53,"end":55,"reading":"まぎょう"},{"start":62,"end":64,"reading":"はってん"},{"start":66,"end":67,"reading":"いの"},{"start":68,"end":69,"reading":"もう"},{"start":70,"end":71,"reading":"あ"},{"start":75,"end":77,"reading":"けいぐ"},{"start":78,"end":80,"reading":"ゆうしゃ"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "裏にもう一行ございます。「追伸　かぶが採れましたら、ひと箱お送りします。」", ruby: [{"start":0,"end":1,"reading":"うら"},{"start":4,"end":6,"reading":"いちぎょう"},{"start":13,"end":15,"reading":"ついしん"},{"start":19,"end":20,"reading":"と"},{"start":28,"end":29,"reading":"はこ"},{"start":30,"end":31,"reading":"おく"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "玉座の間が静まりかえった。高窓から夕陽が斜めに差しこみ、石柱の影を長く引きのばしている。一本、また一本と床に横たわるそれは、誰も座ろうとしないベンチの列のようだった。", ruby: [{"start":0,"end":2,"reading":"ぎょくざ"},{"start":3,"end":4,"reading":"ま"},{"start":5,"end":6,"reading":"しず"},{"start":13,"end":15,"reading":"たかまど"},{"start":17,"end":19,"reading":"ゆうひ"},{"start":20,"end":21,"reading":"なな"},{"start":23,"end":24,"reading":"さ"},{"start":28,"end":30,"reading":"せきちゅう"},{"start":31,"end":32,"reading":"かげ"},{"start":33,"end":34,"reading":"なが"},{"start":35,"end":36,"reading":"ひ"},{"start":44,"end":46,"reading":"いっぽん"},{"start":49,"end":51,"reading":"いっぽん"},{"start":52,"end":53,"reading":"ゆか"},{"start":54,"end":55,"reading":"よこ"},{"start":62,"end":63,"reading":"だれ"},{"start":64,"end":65,"reading":"すわ"},{"start":75,"end":76,"reading":"れつ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）かぶ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は手紙を受け取り、もう一度読んだ。字に震えはなく、書き損じもない。下書きをしてから清書したのが見てとれた。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":4,"reading":"てがみ"},{"start":5,"end":6,"reading":"う"},{"start":7,"end":8,"reading":"と"},{"start":12,"end":14,"reading":"いちど"},{"start":14,"end":15,"reading":"よ"},{"start":18,"end":19,"reading":"じ"},{"start":20,"end":21,"reading":"ふる"},{"start":26,"end":27,"reading":"か"},{"start":28,"end":29,"reading":"そこ"},{"start":34,"end":36,"reading":"したが"},{"start":42,"end":44,"reading":"せいしょ"},{"start":48,"end":49,"reading":"み"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "礼儀正しい手紙だった。そこがいちばん、たちが悪い。", ruby: [{"start":0,"end":3,"reading":"れいぎただ"},{"start":5,"end":7,"reading":"てがみ"},{"start":22,"end":23,"reading":"わる"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "呪われた勇者は戻ってくる。倒された勇者も戻ってくる。恨みを抱いた勇者なら、必ず戻ってくる。", ruby: [{"start":0,"end":1,"reading":"のろ"},{"start":4,"end":6,"reading":"ゆうしゃ"},{"start":7,"end":8,"reading":"もど"},{"start":13,"end":14,"reading":"たお"},{"start":17,"end":19,"reading":"ゆうしゃ"},{"start":20,"end":21,"reading":"もど"},{"start":26,"end":27,"reading":"うら"},{"start":29,"end":30,"reading":"いだ"},{"start":32,"end":34,"reading":"ゆうしゃ"},{"start":37,"end":38,"reading":"かなら"},{"start":39,"end":40,"reading":"もど"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "礼儀正しい勇者は、戻ってこない。", ruby: [{"start":0,"end":3,"reading":"れいぎただ"},{"start":5,"end":7,"reading":"ゆうしゃ"},{"start":9,"end":10,"reading":"もど"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "セリン、今日は何日だ。", ruby: [{"start":4,"end":6,"reading":"きょう"},{"start":7,"end":9,"reading":"なんにち"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Weary },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "十四日です。", ruby: [{"start":0,"end":3,"reading":"じゅうよっか"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "月末を過ぎれば、もう誰も余を倒しには来ないということか。", ruby: [{"start":0,"end":2,"reading":"げつまつ"},{"start":3,"end":4,"reading":"す"},{"start":10,"end":11,"reading":"だれ"},{"start":12,"end":13,"reading":"よ"},{"start":14,"end":15,"reading":"たお"},{"start":18,"end":19,"reading":"こ"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "文面を拝見する限り、そのとおりかと。", ruby: [{"start":0,"end":2,"reading":"ぶんめん"},{"start":3,"end":5,"reading":"はいけん"},{"start":7,"end":8,"reading":"かぎ"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は玉座に背をあずけた。玉座は硬い。三百年前に彼が自ら選んだもので、決め手は「座ると威厳が出るから」だった。いつかこの上で、何をすればいいのかわからないまま座りつづける日が来るなど、考えたこともなかった。", ruby: [{"start":0,"end":2,"reading":"まおう"},{"start":3,"end":5,"reading":"ぎょくざ"},{"start":6,"end":7,"reading":"せ"},{"start":13,"end":15,"reading":"ぎょくざ"},{"start":16,"end":17,"reading":"かた"},{"start":19,"end":23,"reading":"さんびゃくねんまえ"},{"start":24,"end":25,"reading":"かれ"},{"start":26,"end":27,"reading":"みずか"},{"start":28,"end":29,"reading":"えら"},{"start":35,"end":36,"reading":"き"},{"start":37,"end":38,"reading":"て"},{"start":40,"end":41,"reading":"すわ"},{"start":43,"end":45,"reading":"いげん"},{"start":46,"end":47,"reading":"で"},{"start":60,"end":61,"reading":"うえ"},{"start":63,"end":64,"reading":"なに"},{"start":79,"end":80,"reading":"すわ"},{"start":85,"end":86,"reading":"ひ"},{"start":87,"end":88,"reading":"く"},{"start":92,"end":93,"reading":"かんが"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼のカレンダーには、毎月第一土曜日に赤い丸がついている。その前の晩には罠を点検し、誰もいない大広間に向かって口上を一度通しで練習し、マントをクリーニングに出す。あの赤い丸が、ひと月をまるごと支えていた。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":10,"end":12,"reading":"まいつき"},{"start":12,"end":14,"reading":"だいいち"},{"start":14,"end":17,"reading":"どようび"},{"start":18,"end":19,"reading":"あか"},{"start":20,"end":21,"reading":"まる"},{"start":30,"end":31,"reading":"まえ"},{"start":32,"end":33,"reading":"ばん"},{"start":35,"end":36,"reading":"わな"},{"start":37,"end":39,"reading":"てんけん"},{"start":41,"end":42,"reading":"だれ"},{"start":46,"end":49,"reading":"おおひろま"},{"start":50,"end":51,"reading":"む"},{"start":54,"end":56,"reading":"こうじょう"},{"start":57,"end":59,"reading":"いちど"},{"start":59,"end":60,"reading":"とお"},{"start":62,"end":64,"reading":"れんしゅう"},{"start":77,"end":78,"reading":"だ"},{"start":82,"end":83,"reading":"あか"},{"start":84,"end":85,"reading":"まる"},{"start":89,"end":90,"reading":"つき"},{"start":95,"end":96,"reading":"ささ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）この先は、白紙があるだけだ。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":7,"end":8,"reading":"さき"},{"start":10,"end":12,"reading":"はくし"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "勇者のいない魔王など、ただ大きな家に住んでいるだけの者にすぎん。", ruby: [{"start":0,"end":2,"reading":"ゆうしゃ"},{"start":6,"end":8,"reading":"まおう"},{"start":13,"end":14,"reading":"おお"},{"start":16,"end":17,"reading":"いえ"},{"start":18,"end":19,"reading":"す"},{"start":26,"end":27,"reading":"もの"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "たしかに、大きなお住まいです。", ruby: [{"start":5,"end":6,"reading":"おお"},{"start":9,"end":10,"reading":"す"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "そういう話ではない。", ruby: [{"start":4,"end":5,"reading":"はなし"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "存じております。", ruby: [{"start":0,"end":1,"reading":"ぞん"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "セリンが彼に仕えて百十年になる。そのあいだ、一度も取り乱したことがない。東翼が火事になったときも、地下牢のスライムが一斉にストライキを起こしたときも、勇者がはじめて攻め込んできて魔王が口上を忘れたときも。", ruby: [{"start":4,"end":5,"reading":"かれ"},{"start":6,"end":7,"reading":"つか"},{"start":9,"end":12,"reading":"ひゃくじゅうねん"},{"start":22,"end":24,"reading":"いちど"},{"start":25,"end":26,"reading":"と"},{"start":27,"end":28,"reading":"みだ"},{"start":36,"end":38,"reading":"とうよく"},{"start":39,"end":41,"reading":"かじ"},{"start":49,"end":52,"reading":"ちかろう"},{"start":58,"end":60,"reading":"いっせい"},{"start":67,"end":68,"reading":"お"},{"start":75,"end":77,"reading":"ゆうしゃ"},{"start":82,"end":83,"reading":"せ"},{"start":84,"end":85,"reading":"こ"},{"start":89,"end":91,"reading":"まおう"},{"start":92,"end":94,"reading":"こうじょう"},{"start":95,"end":96,"reading":"わす"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は手にしたファイルを開き、紙を一枚抜き出した。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"て"},{"start":12,"end":13,"reading":"ひら"},{"start":15,"end":16,"reading":"かみ"},{"start":17,"end":19,"reading":"いちまい"},{"start":19,"end":20,"reading":"ぬ"},{"start":21,"end":22,"reading":"だ"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "では、補充いたしましょう。", ruby: [{"start":3,"end":5,"reading":"ほじゅう"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "何をだ。", ruby: [{"start":0,"end":1,"reading":"なに"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "勇者です。欠員が出たら、募集をかける。それだけのことです。", ruby: [{"start":0,"end":2,"reading":"ゆうしゃ"},{"start":5,"end":7,"reading":"けついん"},{"start":8,"end":9,"reading":"で"},{"start":12,"end":14,"reading":"ぼしゅう"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "宿敵は欠員ではない。", ruby: [{"start":0,"end":2,"reading":"しゅくてき"},{"start":3,"end":5,"reading":"けついん"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "本日午前九時付で、欠員となりました。", ruby: [{"start":0,"end":2,"reading":"ほんじつ"},{"start":2,"end":4,"reading":"ごぜん"},{"start":4,"end":6,"reading":"くじ"},{"start":6,"end":7,"reading":"づけ"},{"start":9,"end":11,"reading":"けついん"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼女は紙をくるりと回して、魔王のほうへ向けた。求人票だった。城の公印まで、すでに押してある。", ruby: [{"start":0,"end":2,"reading":"かのじょ"},{"start":3,"end":4,"reading":"かみ"},{"start":9,"end":10,"reading":"まわ"},{"start":13,"end":15,"reading":"まおう"},{"start":19,"end":20,"reading":"む"},{"start":23,"end":26,"reading":"きゅうじんひょう"},{"start":30,"end":31,"reading":"しろ"},{"start":32,"end":34,"reading":"こういん"},{"start":40,"end":41,"reading":"お"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "「魔王城　宿敵募集（一名）。応募資格：正義感のある方。定期的に来訪できる方。ストレス耐性のある方。未経験可。給与：応相談。討伐可。」", ruby: [{"start":1,"end":4,"reading":"まおうじょう"},{"start":5,"end":7,"reading":"しゅくてき"},{"start":7,"end":9,"reading":"ぼしゅう"},{"start":10,"end":12,"reading":"いちめい"},{"start":14,"end":18,"reading":"おうぼしかく"},{"start":19,"end":22,"reading":"せいぎかん"},{"start":25,"end":26,"reading":"かた"},{"start":27,"end":30,"reading":"ていきてき"},{"start":31,"end":33,"reading":"らいほう"},{"start":36,"end":37,"reading":"かた"},{"start":42,"end":44,"reading":"たいせい"},{"start":47,"end":48,"reading":"かた"},{"start":49,"end":53,"reading":"みけいけんか"},{"start":54,"end":56,"reading":"きゅうよ"},{"start":57,"end":60,"reading":"おうそうだん"},{"start":61,"end":64,"reading":"とうばつか"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "「討伐可」というのは、余のことか。", ruby: [{"start":1,"end":4,"reading":"とうばつか"},{"start":11,"end":12,"reading":"よ"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "はい。はっきり書いておいたほうが、誠意が伝わるかと。", ruby: [{"start":7,"end":8,"reading":"か"},{"start":17,"end":19,"reading":"せいい"},{"start":20,"end":21,"reading":"つた"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "いつ貼った。", ruby: [{"start":2,"end":3,"reading":"は"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "陛下が手紙を三度目に読み返していらしたときです。ふもとの村の掲示板と、市場の入口の告知板に。", ruby: [{"start":0,"end":2,"reading":"へいか"},{"start":3,"end":5,"reading":"てがみ"},{"start":6,"end":9,"reading":"さんどめ"},{"start":10,"end":11,"reading":"よ"},{"start":12,"end":13,"reading":"かえ"},{"start":28,"end":29,"reading":"むら"},{"start":30,"end":33,"reading":"けいじばん"},{"start":35,"end":37,"reading":"いちば"},{"start":38,"end":40,"reading":"いりぐち"},{"start":41,"end":44,"reading":"こくちばん"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "（心の声）手紙を読み上げる前に、もう書いてあったのだな。", ruby: [{"start":1,"end":2,"reading":"こころ"},{"start":3,"end":4,"reading":"こえ"},{"start":5,"end":7,"reading":"てがみ"},{"start":8,"end":9,"reading":"よ"},{"start":10,"end":11,"reading":"あ"},{"start":13,"end":14,"reading":"まえ"},{"start":18,"end":19,"reading":"か"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "彼は尋ねなかった。百十年も一緒にいれば、聞かずにおいたほうがいいこともある。", ruby: [{"start":0,"end":1,"reading":"かれ"},{"start":2,"end":3,"reading":"たず"},{"start":9,"end":12,"reading":"ひゃくじゅうねん"},{"start":13,"end":15,"reading":"いっしょ"},{"start":20,"end":21,"reading":"き"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "誰か来るのか。", ruby: [{"start":0,"end":1,"reading":"だれ"},{"start":2,"end":3,"reading":"く"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "すでに三名の応募がございました。面接は明日の午前に入れてあります。", ruby: [{"start":3,"end":5,"reading":"さんめい"},{"start":6,"end":8,"reading":"おうぼ"},{"start":16,"end":18,"reading":"めんせつ"},{"start":19,"end":21,"reading":"あす"},{"start":22,"end":24,"reading":"ごぜん"},{"start":25,"end":26,"reading":"い"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Base },
    { characterId: CharacterId.Narrator, character: "ナレーション", dialogue: "魔王は求人票を見つめた。紙は真新しく、墨は黒々としていて、「討伐可」の三文字だけがひときわ端正に書かれていた。", ruby: [{"start":0,"end":2,"reading":"まおう"},{"start":3,"end":6,"reading":"きゅうじんひょう"},{"start":7,"end":8,"reading":"み"},{"start":12,"end":13,"reading":"かみ"},{"start":14,"end":16,"reading":"まあたら"},{"start":19,"end":20,"reading":"すみ"},{"start":21,"end":23,"reading":"くろぐろ"},{"start":30,"end":33,"reading":"とうばつか"},{"start":35,"end":38,"reading":"さんもじ"},{"start":45,"end":47,"reading":"たんせい"},{"start":48,"end":49,"reading":"か"}], background: Background.Root_Act1_S0 },
    { characterId: CharacterId.DemonLord, character: "魔王", dialogue: "……玉座の間は、どう設営する。", ruby: [{"start":2,"end":4,"reading":"ぎょくざ"},{"start":5,"end":6,"reading":"ま"},{"start":10,"end":12,"reading":"せつえい"}], background: Background.Root_Act1_S0, portrait: Portrait.DemonLord_Base },
    { characterId: CharacterId.Serin, character: "セリン", dialogue: "お任せください。", ruby: [{"start":1,"end":2,"reading":"まか"}], background: Background.Root_Act1_S0, portrait: Portrait.Serin_Smile },
];
